"use client";

import { useState } from "react";

export interface SessionMeta {
  id: string;
  title: string;
  model: string;
  updated_at: number;
}

interface Props {
  sessions: SessionMeta[];
  activeId: string | null;
  onSelect: (id: string) => void;
  onNew: () => void;
  onDelete: (id: string) => void;
  onRename: (id: string, title: string) => void;
}

export default function Sidebar({
  sessions,
  activeId,
  onSelect,
  onNew,
  onDelete,
  onRename,
}: Props) {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");

  function startEdit(s: SessionMeta) {
    setEditingId(s.id);
    setEditValue(s.title);
  }

  function commitEdit(id: string) {
    if (editValue.trim()) onRename(id, editValue.trim());
    setEditingId(null);
  }

  return (
    <aside
      style={{
        width: 240,
        minWidth: 240,
        display: "flex",
        flexDirection: "column",
        background: "var(--bg-panel)",
        borderRight: "1px solid var(--border)",
        height: "100%",
        overflow: "hidden",
      }}
    >
      {/* Header */}
      <div
        style={{
          padding: "16px 12px 10px",
          borderBottom: "1px solid var(--border)",
          display: "flex",
          alignItems: "center",
          gap: 8,
        }}
      >
        <span style={{ fontSize: 18 }}>🦙</span>
        <span style={{ fontWeight: 700, fontSize: 15, color: "var(--text-primary)" }}>
          Ollama UI
        </span>
      </div>

      {/* New chat button */}
      <div style={{ padding: "10px 10px 6px" }}>
        <button
          onClick={onNew}
          style={{
            width: "100%",
            padding: "8px 12px",
            background: "var(--accent)",
            color: "#fff",
            border: "none",
            borderRadius: 8,
            cursor: "pointer",
            fontWeight: 600,
            fontSize: 13,
            display: "flex",
            alignItems: "center",
            gap: 6,
          }}
        >
          <span style={{ fontSize: 16 }}>+</span> New Chat
        </button>
      </div>

      {/* Sessions list */}
      <div style={{ flex: 1, overflowY: "auto", padding: "4px 6px" }}>
        {sessions.length === 0 && (
          <p
            style={{
              color: "var(--text-muted)",
              textAlign: "center",
              marginTop: 20,
              fontSize: 12,
            }}
          >
            No chats yet
          </p>
        )}
        {sessions.map((s) => (
          <div
            key={s.id}
            onClick={() => onSelect(s.id)}
            style={{
              padding: "8px 10px",
              borderRadius: 7,
              cursor: "pointer",
              marginBottom: 2,
              background: activeId === s.id ? "var(--bg-active)" : "transparent",
              border: activeId === s.id ? "1px solid var(--border)" : "1px solid transparent",
              display: "flex",
              alignItems: "center",
              gap: 6,
            }}
            onMouseEnter={(e) => {
              if (activeId !== s.id)
                (e.currentTarget as HTMLElement).style.background = "var(--bg-hover)";
            }}
            onMouseLeave={(e) => {
              if (activeId !== s.id)
                (e.currentTarget as HTMLElement).style.background = "transparent";
            }}
          >
            <span style={{ fontSize: 14, flexShrink: 0 }}>💬</span>
            <div style={{ flex: 1, minWidth: 0 }}>
              {editingId === s.id ? (
                <input
                  autoFocus
                  value={editValue}
                  onChange={(e) => setEditValue(e.target.value)}
                  onBlur={() => commitEdit(s.id)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") commitEdit(s.id);
                    if (e.key === "Escape") setEditingId(null);
                  }}
                  onClick={(e) => e.stopPropagation()}
                  style={{
                    background: "var(--bg-input)",
                    border: "1px solid var(--accent)",
                    borderRadius: 4,
                    color: "var(--text-primary)",
                    fontSize: 12,
                    padding: "2px 6px",
                    width: "100%",
                    outline: "none",
                  }}
                />
              ) : (
                <>
                  <div
                    style={{
                      fontSize: 12,
                      fontWeight: 500,
                      color: "var(--text-primary)",
                      whiteSpace: "nowrap",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                    }}
                  >
                    {s.title}
                  </div>
                  <div
                    style={{
                      fontSize: 10,
                      color: "var(--text-muted)",
                      whiteSpace: "nowrap",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                    }}
                  >
                    {s.model.split(":")[0]}
                  </div>
                </>
              )}
            </div>

            {/* Actions */}
            {activeId === s.id && editingId !== s.id && (
              <div style={{ display: "flex", gap: 2, flexShrink: 0 }}>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    startEdit(s);
                  }}
                  title="Rename"
                  style={{
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "var(--text-secondary)",
                    fontSize: 12,
                    padding: "2px 4px",
                    borderRadius: 4,
                  }}
                >
                  ✏️
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    if (confirm("Delete this chat?")) onDelete(s.id);
                  }}
                  title="Delete"
                  style={{
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "var(--danger)",
                    fontSize: 12,
                    padding: "2px 4px",
                    borderRadius: 4,
                  }}
                >
                  🗑️
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </aside>
  );
}
