"use client";

import { useEffect, useRef, useState } from "react";
import Sidebar, { SessionMeta } from "@/components/Sidebar";
import ChatWindow, { ChatMessage } from "@/components/ChatWindow";
import FileBrowser from "@/components/FileBrowser";
import TerminalPanel from "@/components/TerminalPanel";

type Panel = "chat" | "files" | "terminal";

export default function Home() {
  const [sessions, setSessions] = useState<SessionMeta[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [models, setModels] = useState<string[]>([]);
  const [activeModel, setActiveModel] = useState<string>("");
  const [systemPrompt, setSystemPromptState] = useState("");
  const [streaming, setStreaming] = useState(false);
  const [streamingContent, setStreamingContent] = useState("");
  const [activePanel, setActivePanel] = useState<Panel>("chat");
  const [pendingInsert, setPendingInsert] = useState<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  // Load models on mount
  useEffect(() => {
    fetch("/api/models")
      .then((r) => r.json())
      .then((d) => {
        const names: string[] = (d.models ?? []).map((m: { name: string }) => m.name);
        setModels(names);
        if (names.length > 0) setActiveModel(names[0]);
      })
      .catch(console.error);
  }, []);

  // Load sessions on mount
  useEffect(() => {
    loadSessions();
  }, []);

  async function loadSessions() {
    const res = await fetch("/api/sessions");
    const data = await res.json();
    setSessions(data.sessions ?? []);
  }

  async function loadSession(id: string) {
    const res = await fetch(`/api/sessions/${id}`);
    const data = await res.json();
    if (!data.session) return;
    setActiveSessionId(id);
    setMessages(data.messages ?? []);
    setActiveModel(data.session.model);
    setSystemPromptState(data.session.system_prompt ?? "");
  }

  async function createNewSession() {
    if (!activeModel) return;
    const res = await fetch("/api/sessions", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model: activeModel, title: "New Chat" }),
    });
    const data = await res.json();
    if (data.session) {
      await loadSessions();
      await loadSession(data.session.id);
      setActivePanel("chat");
    }
  }

  async function deleteSession(id: string) {
    await fetch(`/api/sessions/${id}`, { method: "DELETE" });
    if (activeSessionId === id) {
      setActiveSessionId(null);
      setMessages([]);
    }
    await loadSessions();
  }

  async function renameSession(id: string, title: string) {
    await fetch(`/api/sessions/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title }),
    });
    await loadSessions();
  }

  async function changeModel(model: string) {
    setActiveModel(model);
    if (!activeSessionId) return;
    await fetch(`/api/sessions/${activeSessionId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model }),
    });
    await loadSessions();
  }

  async function updateSystemPrompt(prompt: string) {
    setSystemPromptState(prompt);
    if (!activeSessionId) return;
    await fetch(`/api/sessions/${activeSessionId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ system_prompt: prompt }),
    });
  }

  async function clearHistory() {
    if (!activeSessionId) return;
    await fetch(`/api/sessions/${activeSessionId}`, { method: "PUT" });
    setMessages([]);
  }

  async function sendMessage(content: string) {
    if (!activeSessionId || streaming) return;

    // Auto-name session on first message
    const session = sessions.find((s) => s.id === activeSessionId);
    if (session && session.title === "New Chat") {
      const autoTitle = content.slice(0, 40) + (content.length > 40 ? "…" : "");
      await renameSession(activeSessionId, autoTitle);
    }

    // Optimistically add user message to UI
    const tempId = "temp-" + Date.now();
    const userMsg: ChatMessage = { id: tempId, role: "user", content };
    setMessages((prev) => [...prev, userMsg]);

    setStreaming(true);
    setStreamingContent("");

    const abort = new AbortController();
    abortRef.current = abort;

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          session_id: activeSessionId,
          content,
          model: activeModel,
        }),
        signal: abort.signal,
      });

      if (!res.ok || !res.body) {
        throw new Error(`HTTP ${res.status}`);
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let accumulated = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split("\n");

        for (const line of lines) {
          if (!line.startsWith("data: ")) continue;
          try {
            const data = JSON.parse(line.slice(6));
            if (data.delta) {
              accumulated += data.delta;
              setStreamingContent(accumulated);
            }
            if (data.done) {
              const assistantMsg: ChatMessage = {
                id: data.id,
                role: "assistant",
                content: accumulated,
              };
              setMessages((prev) => {
                // Remove temp user message, fetch real ones
                return [...prev.filter((m) => m.id !== tempId), assistantMsg];
              });
              // Reload messages from DB to get real user message ID
              loadSession(activeSessionId);
            }
          } catch {
            // skip
          }
        }
      }
    } catch (err: unknown) {
      if ((err as Error)?.name !== "AbortError") {
        console.error(err);
        setMessages((prev) => [
          ...prev,
          {
            id: "err-" + Date.now(),
            role: "assistant",
            content: "❌ Error connecting to Ollama. Is it running?",
          },
        ]);
      }
    } finally {
      setStreaming(false);
      setStreamingContent("");
      abortRef.current = null;
    }
  }

  // Handle file/terminal insert into chat
  function handleInsertToChat(text: string) {
    setPendingInsert(text);
    setActivePanel("chat");
  }

  useEffect(() => {
    if (pendingInsert !== null) {
      // Will be picked up by ChatWindow via prop — pass it down
      setPendingInsert(null);
    }
  }, [pendingInsert]);

  const panelButtons: { id: Panel; label: string; icon: string }[] = [
    { id: "chat", label: "Chat", icon: "💬" },
    { id: "files", label: "Files", icon: "📁" },
    { id: "terminal", label: "Terminal", icon: "📟" },
  ];

  return (
    <div style={{ display: "flex", height: "100vh", overflow: "hidden" }}>
      {/* Sidebar */}
      <Sidebar
        sessions={sessions}
        activeId={activeSessionId}
        onSelect={(id) => { loadSession(id); setActivePanel("chat"); }}
        onNew={createNewSession}
        onDelete={deleteSession}
        onRename={renameSession}
      />

      {/* Main area */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
        {/* Panel switcher tabs */}
        <div
          style={{
            display: "flex",
            borderBottom: "1px solid var(--border)",
            background: "var(--bg-panel)",
            flexShrink: 0,
          }}
        >
          {panelButtons.map((btn) => (
            <button
              key={btn.id}
              onClick={() => setActivePanel(btn.id)}
              style={{
                padding: "10px 18px",
                background: "none",
                border: "none",
                borderBottom: activePanel === btn.id ? "2px solid var(--accent)" : "2px solid transparent",
                color: activePanel === btn.id ? "var(--accent)" : "var(--text-secondary)",
                cursor: "pointer",
                fontSize: 13,
                fontWeight: activePanel === btn.id ? 600 : 400,
                display: "flex",
                alignItems: "center",
                gap: 6,
                transition: "color 0.15s",
              }}
            >
              <span>{btn.icon}</span>
              {btn.label}
            </button>
          ))}

          {/* Ollama status indicator */}
          <div style={{ flex: 1 }} />
          <div
            style={{
              padding: "10px 16px",
              display: "flex",
              alignItems: "center",
              gap: 6,
              fontSize: 11,
              color: "var(--text-muted)",
            }}
          >
            <span
              style={{
                width: 7,
                height: 7,
                borderRadius: "50%",
                background: models.length > 0 ? "var(--success)" : "var(--danger)",
                display: "inline-block",
              }}
            />
            {models.length > 0 ? `${models.length} model${models.length > 1 ? "s" : ""} loaded` : "Ollama offline"}
          </div>
        </div>

        {/* Panel content */}
        <div style={{ flex: 1, overflow: "hidden" }}>
          {activePanel === "chat" && (
            <ChatWindow
              sessionId={activeSessionId}
              messages={messages}
              model={activeModel}
              models={models}
              streaming={streaming}
              streamingContent={streamingContent}
              onSend={sendMessage}
              onModelChange={changeModel}
              onClearHistory={clearHistory}
              onSystemPromptChange={updateSystemPrompt}
              systemPrompt={systemPrompt}
            />
          )}
          {activePanel === "files" && (
            <FileBrowser onInsertToChat={handleInsertToChat} />
          )}
          {activePanel === "terminal" && (
            <TerminalPanel onInsertToChat={handleInsertToChat} />
          )}
        </div>
      </div>
    </div>
  );
}
