"use client";

import { useEffect, useRef, useState } from "react";
import { marked } from "marked";
import hljs from "highlight.js";
import "highlight.js/styles/github-dark.css";

export interface ChatMessage {
  id: string;
  role: "user" | "assistant" | "system";
  content: string;
}

interface Props {
  sessionId: string | null;
  messages: ChatMessage[];
  model: string;
  models: string[];
  streaming: boolean;
  streamingContent: string;
  onSend: (content: string) => void;
  onModelChange: (model: string) => void;
  onClearHistory: () => void;
  onSystemPromptChange: (prompt: string) => void;
  systemPrompt: string;
}

marked.setOptions({ breaks: true });

function renderMarkdown(content: string): string {
  const html = marked.parse(content) as string;
  return html;
}

function MessageBubble({ msg }: { msg: ChatMessage }) {
  const isUser = msg.role === "user";
  const html = renderMarkdown(msg.content);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (ref.current) {
      ref.current.querySelectorAll("pre code").forEach((block) => {
        hljs.highlightElement(block as HTMLElement);
      });
    }
  }, [html]);

  function copyCode(e: React.MouseEvent) {
    const pre = (e.currentTarget as HTMLElement).closest(".code-block-wrapper")?.querySelector("pre");
    if (pre) navigator.clipboard.writeText(pre.innerText);
  }

  // Wrap pre blocks with copy button
  const wrappedHtml = html.replace(
    /<pre>/g,
    `<div class="code-block-wrapper" style="position:relative"><button class="copy-btn" title="Copy" style="position:absolute;top:8px;right:8px;background:var(--bg-active);border:1px solid var(--border);color:var(--text-secondary);border-radius:4px;padding:2px 8px;cursor:pointer;font-size:11px;z-index:1">Copy</button><pre>`
  ).replace(/<\/pre>/g, "</pre></div>");

  return (
    <div
      style={{
        display: "flex",
        flexDirection: isUser ? "row-reverse" : "row",
        gap: 10,
        marginBottom: 16,
        alignItems: "flex-start",
      }}
    >
      {/* Avatar */}
      <div
        style={{
          width: 30,
          height: 30,
          borderRadius: "50%",
          background: isUser ? "var(--accent-dim)" : "var(--bg-active)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 14,
          flexShrink: 0,
        }}
      >
        {isUser ? "👤" : "🦙"}
      </div>

      {/* Bubble */}
      <div
        style={{
          maxWidth: "78%",
          background: isUser ? "var(--user-bubble)" : "var(--assistant-bubble)",
          border: "1px solid var(--border)",
          borderRadius: isUser ? "14px 4px 14px 14px" : "4px 14px 14px 14px",
          padding: "10px 14px",
        }}
      >
        <div
          ref={ref}
          className="prose"
          style={{ color: "var(--text-primary)" }}
          dangerouslySetInnerHTML={{ __html: wrappedHtml }}
          onClick={(e) => {
            if ((e.target as HTMLElement).classList.contains("copy-btn")) {
              copyCode(e);
              const btn = e.target as HTMLButtonElement;
              btn.textContent = "Copied!";
              setTimeout(() => (btn.textContent = "Copy"), 1500);
            }
          }}
        />
      </div>
    </div>
  );
}

function StreamingBubble({ content }: { content: string }) {
  const html = renderMarkdown(content + " ▋");
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (ref.current) {
      ref.current.querySelectorAll("pre code").forEach((block) => {
        hljs.highlightElement(block as HTMLElement);
      });
    }
  });

  return (
    <div style={{ display: "flex", gap: 10, marginBottom: 16, alignItems: "flex-start" }}>
      <div
        style={{
          width: 30,
          height: 30,
          borderRadius: "50%",
          background: "var(--bg-active)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 14,
          flexShrink: 0,
        }}
      >
        🦙
      </div>
      <div
        style={{
          maxWidth: "78%",
          background: "var(--assistant-bubble)",
          border: "1px solid var(--border)",
          borderRadius: "4px 14px 14px 14px",
          padding: "10px 14px",
        }}
      >
        <div
          ref={ref}
          className="prose"
          style={{ color: "var(--text-primary)" }}
          dangerouslySetInnerHTML={{ __html: html }}
        />
      </div>
    </div>
  );
}

export default function ChatWindow({
  sessionId,
  messages,
  model,
  models,
  streaming,
  streamingContent,
  onSend,
  onModelChange,
  onClearHistory,
  onSystemPromptChange,
  systemPrompt,
}: Props) {
  const [input, setInput] = useState("");
  const [showSystem, setShowSystem] = useState(false);
  const [localSystemPrompt, setLocalSystemPrompt] = useState(systemPrompt);
  const bottomRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, streamingContent]);

  useEffect(() => {
    setLocalSystemPrompt(systemPrompt);
  }, [systemPrompt]);

  function handleSend() {
    const trimmed = input.trim();
    if (!trimmed || streaming || !sessionId) return;
    setInput("");
    if (textareaRef.current) textareaRef.current.style.height = "auto";
    onSend(trimmed);
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  }

  function autoResize(e: React.ChangeEvent<HTMLTextAreaElement>) {
    setInput(e.target.value);
    const ta = e.target;
    ta.style.height = "auto";
    ta.style.height = Math.min(ta.scrollHeight, 180) + "px";
  }

  if (!sessionId) {
    return (
      <div
        style={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexDirection: "column",
          gap: 12,
          color: "var(--text-muted)",
        }}
      >
        <span style={{ fontSize: 48 }}>🦙</span>
        <p style={{ fontSize: 16, fontWeight: 500 }}>Select a chat or start a new one</p>
      </div>
    );
  }

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        height: "100%",
        overflow: "hidden",
      }}
    >
      {/* Toolbar */}
      <div
        style={{
          padding: "10px 16px",
          borderBottom: "1px solid var(--border)",
          display: "flex",
          alignItems: "center",
          gap: 10,
          flexShrink: 0,
          background: "var(--bg-panel)",
        }}
      >
        {/* Model switcher */}
        <select
          value={model}
          onChange={(e) => onModelChange(e.target.value)}
          style={{
            background: "var(--bg-input)",
            border: "1px solid var(--border)",
            color: "var(--text-primary)",
            borderRadius: 7,
            padding: "5px 10px",
            fontSize: 13,
            cursor: "pointer",
            outline: "none",
          }}
        >
          {models.map((m) => (
            <option key={m} value={m}>
              {m}
            </option>
          ))}
        </select>

        <button
          onClick={() => setShowSystem((v) => !v)}
          title="System prompt"
          style={{
            background: showSystem ? "var(--accent-dim)" : "var(--bg-input)",
            border: "1px solid var(--border)",
            color: showSystem ? "var(--accent)" : "var(--text-secondary)",
            borderRadius: 7,
            padding: "5px 10px",
            fontSize: 12,
            cursor: "pointer",
          }}
        >
          ⚙️ System
        </button>

        <div style={{ flex: 1 }} />

        <button
          onClick={() => { if (confirm("Clear all messages?")) onClearHistory(); }}
          title="Clear history"
          style={{
            background: "none",
            border: "1px solid var(--border)",
            color: "var(--text-muted)",
            borderRadius: 7,
            padding: "5px 10px",
            fontSize: 12,
            cursor: "pointer",
          }}
        >
          🗑️ Clear
        </button>
      </div>

      {/* System prompt editor */}
      {showSystem && (
        <div
          style={{
            padding: "10px 16px",
            borderBottom: "1px solid var(--border)",
            background: "var(--bg-input)",
            flexShrink: 0,
          }}
        >
          <label style={{ fontSize: 11, color: "var(--text-muted)", display: "block", marginBottom: 4 }}>
            System Prompt
          </label>
          <div style={{ display: "flex", gap: 8 }}>
            <textarea
              value={localSystemPrompt}
              onChange={(e) => setLocalSystemPrompt(e.target.value)}
              placeholder="You are a helpful assistant..."
              rows={3}
              style={{
                flex: 1,
                background: "var(--bg-panel)",
                border: "1px solid var(--border)",
                color: "var(--text-primary)",
                borderRadius: 6,
                padding: "6px 10px",
                fontSize: 12,
                resize: "vertical",
                outline: "none",
                fontFamily: "inherit",
              }}
            />
            <button
              onClick={() => onSystemPromptChange(localSystemPrompt)}
              style={{
                background: "var(--accent)",
                border: "none",
                color: "#fff",
                borderRadius: 6,
                padding: "6px 12px",
                cursor: "pointer",
                fontSize: 12,
                alignSelf: "flex-start",
              }}
            >
              Save
            </button>
          </div>
        </div>
      )}

      {/* Messages */}
      <div
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "16px 20px",
        }}
      >
        {messages.length === 0 && !streaming && (
          <div
            style={{
              textAlign: "center",
              color: "var(--text-muted)",
              marginTop: 60,
              fontSize: 13,
            }}
          >
            <p>No messages yet. Say something!</p>
          </div>
        )}
        {messages.map((m) => (
          <MessageBubble key={m.id} msg={m} />
        ))}
        {streaming && <StreamingBubble content={streamingContent} />}
        <div ref={bottomRef} />
      </div>

      {/* Input */}
      <div
        style={{
          padding: "12px 16px",
          borderTop: "1px solid var(--border)",
          background: "var(--bg-panel)",
          flexShrink: 0,
        }}
      >
        <div
          style={{
            display: "flex",
            gap: 8,
            alignItems: "flex-end",
            background: "var(--bg-input)",
            border: "1px solid var(--border)",
            borderRadius: 10,
            padding: "8px 12px",
          }}
        >
          <textarea
            ref={textareaRef}
            value={input}
            onChange={autoResize}
            onKeyDown={handleKeyDown}
            disabled={streaming}
            placeholder="Message... (Enter to send, Shift+Enter for newline)"
            rows={1}
            style={{
              flex: 1,
              background: "none",
              border: "none",
              color: "var(--text-primary)",
              fontSize: 14,
              resize: "none",
              outline: "none",
              fontFamily: "inherit",
              lineHeight: 1.5,
              minHeight: 22,
              maxHeight: 180,
            }}
          />
          <button
            onClick={handleSend}
            disabled={streaming || !input.trim()}
            style={{
              background: streaming || !input.trim() ? "var(--bg-active)" : "var(--accent)",
              border: "none",
              color: streaming || !input.trim() ? "var(--text-muted)" : "#fff",
              borderRadius: 7,
              padding: "6px 14px",
              cursor: streaming || !input.trim() ? "not-allowed" : "pointer",
              fontSize: 14,
              fontWeight: 600,
              transition: "background 0.15s",
              flexShrink: 0,
            }}
          >
            {streaming ? "..." : "Send"}
          </button>
        </div>
        <p style={{ fontSize: 10, color: "var(--text-muted)", marginTop: 4, textAlign: "center" }}>
          Running locally via Ollama · no data leaves your machine
        </p>
      </div>
    </div>
  );
}
